create table if not exists public.audit_log(log_id bigint generated always as identity primary key,user_id bigint references public.users(user_id),action text not null,entity_type text not null,entity_id bigint not null,"timestamp" timestamptz not null default now(),ip_address inet);
create table if not exists public.change_log(change_id bigint generated always as identity primary key,audit_log_id bigint not null references public.audit_log(log_id) on delete cascade,field_name text not null,old_value text,new_value text);
create table if not exists public.event_log(event_id bigint generated always as identity primary key,event_type text not null,source_component text not null,description text not null,"timestamp" timestamptz not null default now());
create table if not exists public.activity_log(activity_id bigint generated always as identity primary key,user_id bigint not null references public.users(user_id),activity_type text not null,path_accessed text not null,"timestamp" timestamptz not null default now());
create table if not exists public.deleted_records(deleted_id bigint generated always as identity primary key,original_table_name text not null,original_record_id bigint not null,deleted_by_user_id bigint not null references public.users(user_id),deleted_at timestamptz not null default now(),record_data_json text not null);
do $$declare t text;begin foreach t in array array['audit_log','change_log','event_log','activity_log','deleted_records'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "audit_select" on public.%I',t);execute format('drop policy if exists "audit_insert" on public.%I',t);execute format('drop policy if exists "audit_update" on public.%I',t);execute format('drop policy if exists "audit_delete" on public.%I',t);execute format('create policy "audit_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "audit_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "audit_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "audit_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
